package net.officefloor.hq.app.holiday;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The holidays on a sheet. */
@Service
public class HolidayService {

    private final HolidayRepository holidays;
    private final SheetService sheets;
    private final SheetRepository sheetStore;
    private final Audit audit;

    public HolidayService(HolidayRepository holidays, SheetService sheets, SheetRepository sheetStore, Audit audit) {
        this.holidays = holidays;
        this.sheets = sheets;
        this.sheetStore = sheetStore;
        this.audit = audit;
    }

    /** The sheet's holidays, earliest first. */
    @Transactional(readOnly = true)
    public List<Holiday> list(String sheetId) {
        return holidays.findBySheetIdOrderByDateAsc(sheetId);
    }

    /** Add a holiday to the sheet; refused when the date is already on its list. Claims already made keep their
     *  due-by. */
    @Transactional
    public Holiday add(String sheetId, String user, LocalDate date) {
        sheets.load(sheetId, user);
        sheetStore.findLockedById(sheetId).orElseThrow();
        if (holidays.existsBySheetIdAndDate(sheetId, date)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That date is already a holiday");
        }
        Holiday saved;
        try {
            saved = holidays.saveAndFlush(new Holiday(sheetId, date));
        } catch (DataIntegrityViolationException raced) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That date is already a holiday");
        }
        audit.recordChangeOnCommit(sheetId, user, "HOLIDAY_ADDED sheet=" + sheetId + " by=" + user
                + " date=" + saved.getDate());
        return saved;
    }

    /** The day a claim dated {@code date} on {@code terms} is due by: the terms-th business day after its date,
     *  counting forward from the day after it and skipping every Saturday, Sunday and holiday on the sheet now;
     *  its date itself on terms of 0. */
    @Transactional(readOnly = true)
    public LocalDate dueBy(String sheetId, LocalDate date, int terms) {
        Set<LocalDate> dates = holidays.findBySheetIdOrderByDateAsc(sheetId).stream().map(Holiday::getDate)
                .collect(Collectors.toSet());
        return businessDaysAfter(date, terms, dates);
    }

    /** The {@code terms}-th business day after {@code date}: counting from the day after it, skipping every
     *  Saturday, Sunday and one of {@code holidays}; {@code date} itself on terms of 0. */
    public static LocalDate businessDaysAfter(LocalDate date, int terms, Set<LocalDate> holidays) {
        LocalDate due = date;
        for (int counted = 0; counted < terms; ) {
            due = due.plusDays(1);
            if (isBusinessDay(due, holidays)) {
                counted++;
            }
        }
        return due;
    }

    private static boolean isBusinessDay(LocalDate day, Set<LocalDate> holidays) {
        DayOfWeek weekday = day.getDayOfWeek();
        return weekday != DayOfWeek.SATURDAY && weekday != DayOfWeek.SUNDAY && !holidays.contains(day);
    }
}
-- The holidays on a sheet: a claim's due-by fixed at its creation is moved past them. Each date is on a sheet's
-- list at most once. Ids rise in the order holidays were added.
CREATE TABLE holiday (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet (id),
    holiday_date DATE         NOT NULL
);
CREATE UNIQUE INDEX holiday_sheet_date ON holiday (sheet_id, holiday_date);
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, tap } from 'rxjs';

/** A holiday on the sheet: a claim's due-by fixed at its creation skips it when counting its terms in business days. */
export interface HolidayView {
  id: number;
  date: string;
}

// The holidays on the active sheet, earliest first.
@Injectable({ providedIn: 'root' })
export class Holidays {
  private readonly http = inject(HttpClient);
  private readonly list = signal<HolidayView[]>([]);
  readonly all = this.list.asReadonly();

  /** Re-read a sheet's holidays from the store; null clears them. */
  load(sheetId: string | null): Observable<HolidayView[]> | null {
    this.list.set([]);
    if (sheetId === null) return null;
    return this.http.get<HolidayView[]>(this.base(sheetId)).pipe(tap((list) => this.list.set(list)));
  }

  /** Add a holiday; refused when the date is already on the list. */
  add(sheetId: string, date: string): Observable<HolidayView> {
    return this.http.post<HolidayView>(this.base(sheetId), { date }).pipe(
      tap((saved) =>
        this.list.update((list) => [...list, saved].sort((a, b) => a.date.localeCompare(b.date))),
      ),
    );
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/holidays`;
  }
}
import { Component, inject, signal } from '@angular/core';
import { takeUntilDestroyed, toObservable } from '@angular/core/rxjs-interop';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { EMPTY, switchMap } from 'rxjs';
import { Holidays } from '../../core/holidays';
import { Sheets } from '../../core/sheet';

/** A date the form accepts: yyyy-mm-dd. */
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

// The sheet's holidays: a claim whose date plus its terms falls on one is due by the next day that is not a holiday.
@Component({
  selector: 'app-holidays',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="holidays-heading">
      <h3 id="holidays-heading">Holidays</h3>
      <p>A claim made while a date is on this list is not due by it, but by the next day that is not a holiday.</p>
      <ul aria-label="Holidays">
        @for (h of holidays.all(); track h.id) {
          <li [attr.data-testid]="'holiday-row-' + h.date">{{ h.date }}</li>
        }
      </ul>

      <form [formGroup]="form" (ngSubmit)="add()" aria-label="Add a holiday">
        <label for="holiday-date">Holiday</label>
        <input id="holiday-date" type="date" data-testid="holiday-date" formControlName="date" />
        <button type="submit" data-testid="holiday-add" [disabled]="saving()">Add holiday</button>
        @if (error(); as err) {
          <p role="alert" data-testid="holiday-error">{{ err }}</p>
        }
      </form>
    </section>
  `,
})
export class HolidaysPanel {
  protected readonly holidays = inject(Holidays);
  private readonly sheets = inject(Sheets);

  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);
  protected readonly form = new FormGroup({
    date: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    // Each (re)load of a sheet re-reads its holidays from the store.
    toObservable(this.sheets.loaded)
      .pipe(
        switchMap((sheet) => {
          this.error.set(null);
          return this.holidays.load(sheet?.id ?? null) ?? EMPTY;
        }),
        takeUntilDestroyed(),
      )
      .subscribe({ error: () => this.error.set('Could not read the holidays.') });
    // An error is removed as soon as its form is changed.
    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
  }

  protected add(): void {
    // A second submit before the first has answered is ignored, so it stores one holiday.
    if (this.saving()) return;
    this.error.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const date = this.form.controls.date.value.trim();
    if (!DATE_PATTERN.test(date)) {
      this.error.set('Choose the date of the holiday.');
      return;
    }
    this.saving.set(true);
    this.holidays.add(sheet.id, date).subscribe({
      next: () => this.saving.set(false),
      error: () => {
        this.saving.set(false);
        this.error.set('Could not add the holiday: that date may already be on the list.');
      },
    });
  }
}

